-- Migration: Year 4 - Ethics, Law & Health Systems (PART 4: 151-200)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — Private Insurance & COBRA

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- SECTION: PRIVATE INSURANCE TYPES (HMO, PPO, POS, EPO)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is a defining characteristic of a Health Maintenance Organization (HMO)?', '["Total freedom to choose any provider", "Lower premiums combined with a restricted network and mandatory PCP gatekeeping", "High premiums and no referrals needed", "Only covers emergency care"]', 1, 'HMOs control costs by limiting providers and requiring a primary care physician (PCP) to coordinate all care.'),
    (v_topic_id, 'In an HMO, what is the role of the "Gatekeeper"?', '["A security guard at the hospital", "The Primary Care Physician (PCP) who must authorize all specialty referrals", "The insurance company clerk who pays the bills", "The hospital CEO"]', 1, 'The PCP gatekeeper ensures that specialty care is medically necessary and kept within the network.'),
    (v_topic_id, 'A "Preferred Provider Organization" (PPO) differs from an HMO in that a PPO:', '["Does not allow out-of-network care", "Usually allows members to see specialists without a referral and provides some coverage for out-of-network care", "Has lower premiums than an HMO", "Is run by the government"]', 1, 'PPOs offer more choice and flexibility in exchange for higher premiums and higher out-of-pocket costs for out-of-network care.'),
    (v_topic_id, 'A "Point of Service" (POS) plan is often described as a hybrid because:', '["It only works on weekends", "It combines HMO-style gatekeeping for in-network care with PPO-style options for out-of-network care", "It is both a bank and an insurance company", "It covers both humans and pets"]', 1, 'POS plans require a PCP but allow members to "point" to out-of-network care at the time of service, albeit at a higher cost.'),
    (v_topic_id, 'An "Exclusive Provider Organization" (EPO) is similar to a PPO but with one major restriction:', '["It has no deductible", "It generally provides NO coverage for out-of-network care (except for emergencies)", "It requires a referral for every visit", "It is only for government employees"]', 1, 'EPOs allow you to skip the referral (like a PPO) but restrict you to a specific network (like an HMO).'),
    (v_topic_id, 'Which of the following describes "Closed-Panel" HMOs?', '["They are only open during business hours", "Physicians are either employees of the HMO or belong to a group that contracts exclusively with the HMO", "The patient cannot see the doctor alone", "None of the above"]', 1, 'Closed-panel HMOs (e.g., Kaiser Permanente) have very high levels of integration.'),
    (v_topic_id, 'Which of the following describes an "Independent Practice Association" (IPA) model HMO?', '["The HMO owns the hospital", "The HMO contracts with a group of independent physicians who continue to see patients from other plans in their own offices", "The doctors work for the government", "There are no doctors, only nurses"]', 1, 'IPAs allow physicians to maintain their own practices while seeing HMO members.'),

    -- SECTION: COST-SHARING & FINANCING
    (v_topic_id, 'The "Premium" of a health insurance policy is:', '["The amount paid at the doctor''s office", "The monthly fee paid to the insurance company to keep the policy active", "The maximum the insurance will pay", "A bonus given to healthy patients"]', 1, 'Premiums must be paid regardless of whether medical services are used.'),
    (v_topic_id, 'A "Deductible" is:', '["A discount on medications", "The amount the patient must pay out-of-pocket before the insurance company begins to pay for covered services", "The total amount of tax removed from a paycheck", "The fee for a specialist visit"]', 1, 'High-deductible plans require significant front-end spending by the patient.'),
    (v_topic_id, '"Coinsurance" is a cost-sharing method where the patient pays:', '["A fixed dollar amount per visit", "A percentage of the total cost of a service (e.g., 20%)", "Only for medications", "Nothing after the first visit"]', 1, 'Coinsurance is common in PPOs and Medicare Part B.'),
    (v_topic_id, 'A "Copayment" (Copay) is:', '["A percentage of the bill", "A fixed dollar amount paid at the time of service (e.g., $25 per office visit)", "The full cost of the visit", "A payment made by the employer"]', 1, 'Copays are fixed amounts that do not usually count toward a deductible but may count toward the out-of-pocket maximum.'),
    (v_topic_id, 'The "Out-of-Pocket Maximum" (OOPM) is:', '["The most the insurance company will pay in a year", "The most a patient will have to pay in a year for covered services (excluding premiums)", "A limit on the number of doctor visits", "The size of a patient''s wallet"]', 1, 'Once the OOPM is reached, the insurance plan pays 100% of covered charges for the rest of the year.'),
    (v_topic_id, 'Which of the following is true about "Balance Billing"?', '["It is common in all HMOs", "It occurs when a provider bills the patient for the difference between their charge and the insurance-approved amount (common with out-of-network providers)", "It is a way to pay for a hospital stay in installments", "It is illegal for all doctors in the US"]', 1, 'The "No Surprises Act" now protects patients from balance billing in many emergency and out-of-network hospital situations.'),

    -- SECTION: HDHP, HSA, and FSA
    (v_topic_id, 'A "High-Deductible Health Plan" (HDHP) is characterized by:', '["High monthly premiums and low deductibles", "Lower monthly premiums and a high annual deductible", "No coverage for major surgery", "Only covering catastrophic accidents"]', 1, 'HDHPs are popular for their low monthly cost but require budgeting for initial medical expenses.'),
    (v_topic_id, 'To be eligible to open and contribute to a "Health Savings Account" (HSA), an individual MUST be enrolled in:', '["A Medicare Advantage plan", "A qualifying High-Deductible Health Plan (HDHP)", "A Medicaid managed care plan", "Any plan with a copay"]', 1, 'HSAs are legally linked to HDHPs to encourage consumers to be more cost-conscious.'),
    (v_topic_id, 'Which of the following is a major advantage of an HSA over a Flexible Spending Account (FSA)?', '["FSA funds can be used for gym memberships", "HSA funds roll over from year to year and belong to the individual even if they change jobs", "HSAs are only for government employees", "FSAs have no contribution limits"]', 1, 'FSAs are "use it or lose it" each year; HSAs are portable and permanent.'),
    (v_topic_id, 'Are contributions to an HSA tax-deductible?', '["No", "Yes, they are made with pre-tax dollars, reducing the individual''s taxable income", "Only if the person is over 65", "Only for business owners"]', 1, 'HSAs offer a "triple tax advantage": pre-tax contributions, tax-free growth, and tax-free withdrawals for medical use.'),
    (v_topic_id, 'What happens to HSA funds once a person turns 65?', '["They are forfeited to the government", "They can be withdrawn for any purpose (taxed as income) without a penalty, or still used tax-free for medical expenses", "They must be spent on a car", "They are automatically moved to a Part D plan"]', 1, 'After 65, the 20% penalty for non-medical withdrawals is removed, though income tax still applies.'),

    -- SECTION: REIMBURSEMENT MODELS (PROVIDER PERSPECTIVE)
    (v_topic_id, 'Which reimbursement model pays a physician a fixed amount per patient per month, regardless of how many services are provided?', '["Fee-for-Service", "Capitation", "Salary", "Pay-for-Performance"]', 1, 'Capitation incentivizes efficiency but can lead to "under-service" (moral hazard on the provider side).'),
    (v_topic_id, 'In a "Fee-for-Service" (FFS) model, what is the primary incentive for the physician?', '["To provide as few services as possible", "To provide more services to increase revenue", "To focus only on preventive care", "To work fewer hours"]', 1, 'FFS encourages volume (more tests, more procedures).'),
    (v_topic_id, 'What is a "Withhold" in a managed care contract?', '["A percentage of the provider''s payment that is kept by the plan and only paid out if certain quality or cost targets are met", "A way to stop a surgery in progress", "A tax on medical equipment", "None of the above"]', 0, 'Withholds are used to align physician incentives with the goals of the health plan.'),
    (v_topic_id, 'A "Bundled Payment" (Episode-based payment) is:', '["Paying for each individual cotton ball used", "A single payment that covers all services for a specific procedure (e.g., a hip replacement) from start to finish", "A way to bill multiple patients at once", "A type of insurance premium"]', 1, 'Bundled payments encourage coordination between hospitals, surgeons, and rehab facilities.'),

    -- SECTION: COBRA & CONTINUITY OF COVERAGE
    (v_topic_id, 'What does "COBRA" (Consolidated Omnibus Budget Reconciliation Act) allow an individual to do?', '["Get free health insurance from the government", "Temporarily continue their employer-sponsored health coverage after a "qualifying event" like job loss", "Sue their employer for medical malpractice", "Avoid paying for Medicare"]', 1, 'COBRA is a bridge between jobs but is often very expensive.'),
    (v_topic_id, 'Under COBRA, the individual is typically responsible for paying how much of the health insurance premium?', '["0% (Employer still pays everything)", "The same amount they paid as an employee", "Up to 102% of the total premium (the employee and employer shares plus a 2% administrative fee)", "Whatever they can afford"]', 2, 'Because the employer no longer subsidizes the premium, the cost usually jumps significantly for the individual.'),
    (v_topic_id, 'For a person who loses their job (a "Qualifying Event"), COBRA coverage typically lasts for up to how many months?', '["6 months", "12 months", "18 months", "36 months"]', 2, '18 months is the standard for job loss; 36 months is for events like death of a spouse or divorce.'),
    (v_topic_id, 'COBRA applies to employers with at least how many employees?', '["2 employees", "10 employees", "20 employees", "50 employees"]', 2, 'Federal COBRA only applies to employers with 20 or more employees; many states have "mini-COBRA" laws for smaller firms.'),
    (v_topic_id, 'A "Qualifying Event" for COBRA includes all of the following EXCEPT:', '["Voluntary resignation", "Termination for "gross misconduct"", "Reduction in work hours", "Divorce from the covered employee"]', 1, 'Gross misconduct is one of the few reasons an employer can deny COBRA coverage.'),

    -- SECTION: ERISA & SELF-INSURANCE
    (v_topic_id, 'Which federal law regulates employer-sponsored health and pension plans and "preempts" most state laws for self-insured plans?', '["HIPAA", "COBRA", "ERISA (Employee Retirement Income Security Act)", "The Affordable Care Act"]', 2, 'ERISA is why large national companies often have the same health plan across different states, ignoring state-specific mandates.'),
    (v_topic_id, 'In a "Self-Insured" (Self-funded) health plan:', '["The individual buys insurance on their own", "The employer assumes the financial risk and pays for medical claims out of its own funds, rather than buying a policy from an insurer", "The doctor pays the patient", "The plan is only for self-employed people"]', 1, 'Large employers often use self-insurance to gain more control and avoid state insurance taxes.'),
    (v_topic_id, 'What is "Stop-Loss Insurance" in the context of a self-insured employer?', '["Insurance that prevents the company from losing money if an employee quits", "Insurance the employer buys to protect itself against catastrophic medical claims that exceed a certain dollar amount", "A way to stop a patient from getting a test", "None of the above"]', 1, 'Stop-loss protects the company''s budget from one or two extremely expensive cases (e.g., a $1 million NICU stay).'),

    -- SECTION: PRIVATE MARKET CONCEPTS
    (v_topic_id, 'What is "Underwriting" in private insurance?', '["Writing the policy by hand", "The process of assessing a person''s risk (age, health history) to determine their premium or eligibility", "A way to hide costs", "Paying for a medical student''s education"]', 1, 'In the individual market before the ACA, medical underwriting often led to denials for pre-existing conditions.'),
    (v_topic_id, 'A "Tiered Provider Network" differs from a standard network in that:', '["Some doctors are better than others", "Patients pay lower cost-sharing (e.g., smaller copay) if they use "Tier 1" providers who meet specific quality and cost targets", "Only Tier 3 doctors can perform surgery", "The tiers are based on the doctor''s age"]', 1, 'Tiered networks incentivize patients to choose high-value providers within their network.'),
    (v_topic_id, 'What is "Narrow Network" insurance?', '["A plan that only works in one building", "Plans with a very limited number of providers, designed to keep premiums low by negotiating deeper discounts", "Plans for people with narrow chests", "A plan with no specialists"]', 1, 'Narrow networks are common on the ACA marketplaces to keep plans affordable.'),
    (v_topic_id, 'Which of the following is an example of "Direct Primary Care" (DPC)?', '["A patient paying a monthly membership fee directly to a clinic for unlimited primary care, bypassing insurance entirely", "A doctor working for an insurance company", "Medicare paying a doctor", "None of the above"]', 0, 'DPC is a growing alternative model that removes the "middleman" of insurance for basic care.'),
    (v_topic_id, 'What is the "Medical Loss Ratio" (MLR) requirement introduced by the ACA?', '["The percentage of patients who die in a hospital", "The requirement that insurers spend at least 80-85% of premium dollars on medical care and quality improvement, rather than profit and overhead", "The ratio of doctors to nurses", "The amount of money a hospital loses each year"]', 1, 'If an insurer fails to meet the MLR, they must issue rebates to their customers.'),

    -- SECTION: GROUP VS INDIVIDUAL MARKET
    (v_topic_id, 'Which of the following is a "Group Health Plan"?', '["A plan bought by an individual on a website", "A plan offered by an employer or a union to its employees or members", "A plan for a family of four", "A plan that only covers groups of 10 or more"]', 1, 'The group market (mostly ESI) is the largest source of health insurance in the US.'),
    (v_topic_id, 'What is "Guaranteed Issue"?', '["A guarantee that a patient will get well", "A requirement that an insurer must accept every applicant for coverage regardless of their health status", "A promise to pay for every surgery", "A government-issued ID card"]', 1, 'The ACA made "guaranteed issue" the law for all individual and small group plans.'),
    (v_topic_id, 'What is "Community Rating"?', '["Rating a doctor based on their community service", "A system where everyone in the same geographic area pays the same premium regardless of their health status or gender", "A list of the best hospitals in a town", "None of the above"]', 1, 'ACA rules allow premiums to vary only by age (within a 3:1 ratio), tobacco use, and geography.'),

    -- SECTION: SUPPLEMENTAL INSURANCE
    (v_topic_id, 'What does "Critical Illness Insurance" typically provide?', '["Health insurance for the ICU", "A lump-sum cash payment if the patient is diagnosed with a specific condition like cancer or a heart attack", "A list of critical doctors", "None of the above"]', 1, 'This is a supplemental "indemnity" plan, not comprehensive health insurance.'),
    (v_topic_id, '"Long-Term Care Insurance" (LTCI) is designed to pay for:', '["Heart surgeries", "Assistance with Activities of Daily Living (ADLs) in a nursing home or at home", "Cancer treatments", "Vitamins"]', 1, 'Private LTCI is an alternative to relying on Medicaid spend-down for nursing home care.'),
    (v_topic_id, 'Does a "Dental PPO" work like a medical PPO?', '["Yes, it provides a network of dentists and covers more of the cost if you stay in-network", "No, it only covers toothbrushes", "Yes, but there are no specialists in dental", "None of the above"]', 0, 'Dental PPOs are the most common form of private dental coverage.'),

    -- SECTION: BILLING CODES & AUDITS
    (v_topic_id, 'What are "ICD-10" codes used for in medical billing?', '["Identifying the specific procedure performed", "Identifying the patient''s diagnosis or condition", "The doctor''s home phone number", "The hospital''s address"]', 1, 'ICD (International Classification of Diseases) codes justify the "medical necessity" of a service.'),
    (v_topic_id, 'What are "CPT" (Current Procedural Terminology) codes used for?', '["Identifying the diagnosis", "Identifying the specific services or procedures performed by a provider", "Naming the insurance company", "Ordering lunch for the patient"]', 1, 'CPT codes tell the insurer exactly what the doctor did (e.g., a 99213 office visit).'),
    (v_topic_id, 'What is "Upcoding" in medical billing?', '["Using a higher-level code than is justified by the complexity of the service to get higher reimbursement (Fraud)", "Writing in capital letters", "Adding more patients to a plan", "None of the above"]', 0, 'Upcoding is a major focus of federal anti-fraud audits.'),
    (v_topic_id, 'What is "Unbundling" (Fragmentation)?', '["Opening a package of supplies", "Billing multiple codes for parts of a procedure that should be covered by a single comprehensive code to get more money", "Breaking up a large hospital system", "None of the above"]', 1, 'Unbundling is another form of billing fraud or abuse.'),

    -- SECTION: PATIENT PROTECTION
    (v_topic_id, 'The "Summary of Benefits and Coverage" (SBC) is a document that:', '["Lists every patient in a plan", "Provides a standardized, easy-to-understand comparison of a plan''s costs and coverage", "Is a bill for the deductible", "None of the above"]', 1, 'The SBC is mandated by the ACA to help consumers compare different plans.'),
    (v_topic_id, 'If an insurer denies a claim for a medically necessary service, the patient has the right to:', '["Sue the doctor immediately", "An internal and external appeal process", "Nothing, the insurer''s word is final", "Call the police"]', 1, 'Patient appeal rights were strengthened by the ACA.'),
    (v_topic_id, 'Which of the following is a "Surprise Medical Bill"?', '["A bill that arrives in a funny envelope", "A bill for out-of-network services received at an in-network facility that the patient didn''t choose", "A bill for a service the patient forgot they had", "None of the above"]', 1, 'The No Surprises Act (2022) largely protects patients from these bills.')
;

END $$;
COMMIT;
